package javacore2;

public class Twodarry {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int arr[][]=new int [4][4];
		arr[0][0]=10;
		arr[0][1]=20;
		arr[0][2]=30;
		arr[0][3]=40;
		
		for(int i=0;i<arr.length;i++)
		{
			for(int j=0;j<arr.length;j++)
			{
				System.out.println(arr[i][j]+"");
			}
				}
		System.out.println();

	}

}
